/* Big countdown section — DYNAMIC featured event.
   Auto-selects the earliest event that is neither past nor sold out,
   populates the heading/meta/register link, and re-selects automatically
   once that event passes (or is flagged sold out). Add/flag events below. */
(function(){
  var EVENTS=[
    { title:'From Shaking to Shaping &mdash; Online',
      sub:'Online &middot; 8 October 2026 &middot; 7&#8211;9pm',
      metaCal:'Thursday, 8 October 2026', metaLoc:'Live Online', metaIcon:'fa-solid fa-video',
      date:'2026-10-08T19:00:00+02:00', href:'/event-shaking-online', soldOut:false },
    { title:'TRE&#8482; Module 1 &mdash; Bucharest',
      sub:'Bucharest &middot; 15&#8211;17 October 2026',
      metaCal:'15&#8211;17 October 2026', metaLoc:'Bucharest, Romania', metaIcon:'fa-solid fa-location-dot',
      date:'2026-10-15T09:00:00+03:00', href:'/event-tre-module1-bucharest', soldOut:false },
    { title:'Become a Certified TRE&#8482; Provider &mdash; 2027 Cohort',
      sub:'Singapore &middot; Module 1: 24&#8211;25 April 2027',
      metaCal:'24&#8211;25 April 2027', metaLoc:'Singapore', metaIcon:'fa-solid fa-location-dot',
      date:'2027-04-24T09:00:00+08:00', href:'/event-certification-2027', soldOut:false }
  ];
  var sec=document.querySelector('.ecd-section');
  if(!sec)return;
  var now=Date.now();
  var featured=EVENTS.filter(function(e){
      return !e.soldOut && new Date(e.date).getTime()>now;
    }).sort(function(a,b){ return new Date(a.date)-new Date(b.date); })[0];
  if(!featured){ sec.style.display='none'; return; }

  var hEl=sec.querySelector('.ecd-heading');
  if(hEl) hEl.innerHTML=featured.title+'<br><em>'+featured.sub+'</em>';
  var mEl=sec.querySelector('.ecd-meta');
  if(mEl) mEl.innerHTML='<i class="fa-regular fa-calendar"></i> '+featured.metaCal+
    ' <span>&middot;</span> <i class="'+featured.metaIcon+'"></i> '+featured.metaLoc;
  var reg=sec.querySelector('.ecd-actions .btn-primary');
  if(reg) reg.setAttribute('href',featured.href);

  var target=new Date(featured.date).getTime();
  var CIRC=2*Math.PI*54;
  function pad(n){return String(n).padStart(2,'0');}
  function setRing(id,val,max){
    var el=document.getElementById(id);if(!el)return;
    el.style.strokeDashoffset=(CIRC*(1-Math.min(1,Math.max(0,val/max)))).toFixed(2);
  }
  function setNum(id,val){
    var el=document.getElementById(id);if(!el)return;
    var v=pad(val);if(el.textContent===v)return;
    el.classList.remove('ecd-flip');void el.offsetWidth;
    el.textContent=v;el.classList.add('ecd-flip');
  }
  function tickEcd(){
    var diff=target-Date.now();
    if(diff<=0){
      var u=document.getElementById('ecd-units');
      if(u)u.innerHTML='<p style="color:var(--gold);font-size:1.5rem;font-weight:700">Event is happening now!</p>';
      return;
    }
    var d=Math.floor(diff/86400000),h=Math.floor((diff%86400000)/3600000),
        m=Math.floor((diff%3600000)/60000),s=Math.floor((diff%60000)/1000);
    setNum('ecd-days',d);   setRing('rng-days',d,Math.max(90, d + 1));
    setNum('ecd-hours',h);  setRing('rng-hours',h,24);
    setNum('ecd-mins',m);   setRing('rng-mins',m,60);
    setNum('ecd-secs',s);   setRing('rng-secs',s,60);
  }
  tickEcd();setInterval(tickEcd,1000);
})();

/* ===== Date-driven event status: runs fresh on every page load =====
   Each card carries data-start / data-end (ISO, SGT) and optional data-sold.
   Status -> badge (Upcoming/Ongoing/Sold Out/Passed), and passed events are
   moved into the Past Events archive automatically. */
(function(){
  var now = Date.now();
  function ms(d, endOfDay){ return d ? Date.parse(d + (endOfDay ? 'T23:59:59' : 'T00:00:00') + '+08:00') : NaN; }
  var grid = document.getElementById('evt-grid');
  var archive = document.getElementById('evt-archive');

  // 1) colour the individual date pills (skip a manually fixed state, e.g. is-closed)
  document.querySelectorAll('.evt-date-tag').forEach(function(t){
    if(/is-(past|upcoming|ongoing|closed)/.test(t.className)) return;
    var em = ms(t.getAttribute('data-end') || t.getAttribute('data-start'), true);
    var sm = t.getAttribute('data-start') ? ms(t.getAttribute('data-start'), false) : em;
    if(isNaN(em)){ t.classList.add('is-upcoming'); return; }
    if(em < now) t.classList.add('is-past');
    else if(sm <= now && now <= em) t.classList.add('is-ongoing');
    else t.classList.add('is-upcoming');
  });

  var BADGE = { sold:['evt-sold-badge','Sold Out'], past:['evt-past-badge','Passed'],
                ongoing:['evt-ongoing-badge','Ongoing'], upcoming:['evt-upcoming-badge','Upcoming'] };

  function statusOf(card){
    if(card.getAttribute('data-sold') === 'true') return 'sold';
    var em = ms(card.getAttribute('data-end') || card.getAttribute('data-start'), true);
    var sm = card.getAttribute('data-start') ? ms(card.getAttribute('data-start'), false) : em;
    if(!isNaN(em) && em < now) return 'past';
    if(!isNaN(sm) && sm <= now && (isNaN(em) || now <= em)) return 'ongoing';
    return 'upcoming';
  }
  function setBadge(card, status){
    var thumb = card.querySelector('.evt-card-thumb'); if(!thumb) return;
    thumb.querySelectorAll('.evt-sold-badge,.evt-past-badge,.evt-ongoing-badge,.evt-upcoming-badge').forEach(function(b){ b.remove(); });
    card.classList.remove('is-sold','is-past');
    if(status === 'sold') card.classList.add('is-sold');
    if(status === 'past') card.classList.add('is-past');
    var m = BADGE[status]; if(!m) return;
    var b = document.createElement('span'); b.className = m[0]; b.textContent = m[1];
    thumb.insertBefore(b, thumb.firstChild);
  }
  function endActions(card){
    var actions = card.querySelector('.evt-card-actions'); if(!actions) return;
    if(actions.querySelector('.btn-ended')) return;
    var first = actions.querySelector('.btn');
    var ended = document.createElement('span'); ended.className = 'btn btn-ended'; ended.textContent = 'Event Ended';
    if(first) actions.replaceChild(ended, first);
  }

  // 2) badge + auto-place every card by its live status
  document.querySelectorAll('.evt-card').forEach(function(card){
    var status = statusOf(card);
    card.setAttribute('data-status', status);
    setBadge(card, status);
    if(status === 'past'){
      endActions(card);
      if(archive && card.parentElement !== archive) archive.appendChild(card);
    } else if(grid && card.parentElement !== grid){
      card.classList.remove('is-hidden');
      grid.appendChild(card);
    }
  });

  // 3) order the upcoming grid: soonest date first; sold-out pushed to the end
  if(grid){
    var order = { ongoing:0, upcoming:0, sold:1, past:2 };
    var live = [].slice.call(grid.querySelectorAll('.evt-card'));
    live.sort(function(a,b){
      var ga = order[a.getAttribute('data-status')] || 0, gb = order[b.getAttribute('data-status')] || 0;
      if(ga !== gb) return ga - gb;
      var sa = ms(a.getAttribute('data-start'), false), sb = ms(b.getAttribute('data-start'), false);
      if(isNaN(sa)) sa = Infinity; if(isNaN(sb)) sb = Infinity;
      return sa - sb;
    });
    live.forEach(function(c){ grid.appendChild(c); });
  }
})();

/* Event filter + upcoming/past counts (recomputed after status placement) */
(function(){
  var btns  = document.querySelectorAll('.evt-filter-btn');
  var empty = document.getElementById('evt-empty');
  function gridCards(){ return document.querySelectorAll('#evt-grid .evt-card'); }

  var upEl = document.getElementById('evt-count-up'), pastEl = document.getElementById('evt-count-past');
  if (upEl)   upEl.textContent   = gridCards().length;
  if (pastEl) pastEl.textContent = document.querySelectorAll('#evt-archive .evt-card').length;

  function apply(f){
    var shown = 0;
    gridCards().forEach(function(card){
      var match = (f === 'all') || (card.getAttribute('data-cat') || '').indexOf(f) !== -1;
      card.classList.toggle('is-hidden', !match);
      if (match) shown++;
    });
    if (empty) empty.style.display = shown === 0 ? 'block' : 'none';
  }
  btns.forEach(function(btn){
    btn.addEventListener('click', function(){
      btns.forEach(function(b){ b.classList.remove('is-active'); });
      btn.classList.add('is-active');
      apply(btn.getAttribute('data-filter'));
    });
  });
})();
